"""Generate an Abstract Syntax Tree (AST) for C++."""

__author__ = 'nnorwitz@google.com (Neal Norwitz)'


# TODO:
#  * Tokens should never be exported, need to convert to Nodes
#    (return types, parameters, etc.)
#  * Handle static class data for templatized classes
#  * Handle casts (both C++ and C-style)
#  * Handle conditions and loops (if/else, switch, for, while/do)
#
# TODO much, much later:
#  * Handle #define
#  * exceptions


import sys
import traceback

from cpp import keywords
from cpp import tokenize
from cpp import utils


if 'reversed' not in dir(__builtins__):
    # Support Python 2.3 and earlier.
    def reversed(seq):
        for i in range(len(seq)-1, -1, -1):
            yield seq[i]


VISIBILITY_PUBLIC, VISIBILITY_PROTECTED, VISIBILITY_PRIVATE = range(3)

FUNCTION_NONE = 0x00
FUNCTION_CONST = 0x01
FUNCTION_VIRTUAL = 0x02
FUNCTION_PURE_VIRTUAL = 0x04
FUNCTION_CTOR = 0x08
FUNCTION_DTOR = 0x10
FUNCTION_ATTRIBUTE = 0x20
FUNCTION_UNKNOWN_ANNOTATION = 0x40
FUNCTION_THROW = 0x80

"""
These are currently unused.  Should really handle these properly at some point.

TYPE_MODIFIER_INLINE   = 0x010000
TYPE_MODIFIER_EXTERN   = 0x020000
TYPE_MODIFIER_STATIC   = 0x040000
TYPE_MODIFIER_CONST    = 0x080000
TYPE_MODIFIER_REGISTER = 0x100000
TYPE_MODIFIER_VOLATILE = 0x200000
TYPE_MODIFIER_MUTABLE  = 0x400000

TYPE_MODIFIER_MAP = {
    'inline': TYPE_MODIFIER_INLINE,
    'extern': TYPE_MODIFIER_EXTERN,
    'static': TYPE_MODIFIER_STATIC,
    'const': TYPE_MODIFIER_CONST,
    'register': TYPE_MODIFIER_REGISTER,
    'volatile': TYPE_MODIFIER_VOLATILE,
    'mutable': TYPE_MODIFIER_MUTABLE,
    }
"""

_INTERNAL_TOKEN = 'internal'
_NAMESPACE_POP = 'ns-pop'


# TODO(nnorwitz): use this as a singleton for templated_types, etc
# where we don't want to create a new empty dict each time.  It is also const.
class _NullDict(object):
    __contains__ = lambda self: False
    keys = values = items = iterkeys = itervalues = iteritems = lambda self: ()


# TODO(nnorwitz): move AST nodes into a separate module.
class Node(object):
    """Base AST node."""

    def __init__(self, start, end):
        self.start = start
        self.end = end

    def IsDeclaration(self):
        """Returns bool if this node is a declaration."""
        return False

    def IsDefinition(self):
        """Returns bool if this node is a definition."""
        return False

    def IsExportable(self):
        """Returns bool if this node exportable from a header file."""
        return False

    def Requires(self, node):
        """Does this AST node require the definition of the node passed in?"""
        return False

    def XXX__str__(self):
        return self._StringHelper(self.__class__.__name__, '')

    def _StringHelper(self, name, suffix):
        if not utils.DEBUG:
            return '%s(%s)' % (name, suffix)
        return '%s(%d, %d, %s)' % (name, self.start, self.end, suffix)

    def __repr__(self):
        return str(self)


class Define(Node):
    def __init__(self, start, end, name, definition):
        Node.__init__(self, start, end)
        self.name = name
        self.definition = definition

    def __str__(self):
        value = '%s %s' % (self.name, self.definition)
        return self._StringHelper(self.__class__.__name__, value)


class Include(Node):
    def __init__(self, start, end, filename, system):
        Node.__init__(self, start, end)
        self.filename = filename
        self.system = system

    def __str__(self):
        fmt = '"%s"'
        if self.system:
            fmt = '<%s>'
        return self._StringHelper(self.__class__.__name__, fmt % self.filename)


class Goto(Node):
    def __init__(self, start, end, label):
        Node.__init__(self, start, end)
        self.label = label

    def __str__(self):
        return self._StringHelper(self.__class__.__name__, str(self.label))


class Expr(Node):
    def __init__(self, start, end, expr):
        Node.__init__(self, start, end)
        self.expr = expr

    def Requires(self, node):
        # TODO(nnorwitz): impl.
        return False

    def __str__(self):
        return self._StringHelper(self.__class__.__name__, str(self.expr))


class Return(Expr):
    pass


class Delete(Expr):
    pass


class Friend(Expr):
    pass


class Using(Node):
    def __init__(self, start, end, names):
        Node.__init__(self, start, end)
        self.names = names

    def __str__(self):
        return self._StringHelper(self.__class__.__name__, str(self.names))


class Parameter(Node):
    def __init__(self, start, end, name, type_name, type_modifiers,
                 reference, pointer, templated_types, default):
        Node.__init__(self, start, end)
        self.name = name
        self.type_name = type_name
        self.type_modifiers = type_modifiers
        self.reference = reference
        self.pointer = pointer
        self.default = default
        self.templated_types = templated_types

    def Requires(self, node):
        # TODO(nnorwitz): handle namespaces, etc.
        return self.type_name == node.name

    def __str__(self):
        # TODO(nnorwitz): add templated_types.
        modifiers = ' '.join(self.type_modifiers)
        syntax = ''
        if self.reference:
            syntax += '&'
        if self.pointer:
            syntax += '*'
        suffix = '%s %s%s %s' % (modifiers, self.type_name, syntax, self.name)
        if self.default:
            suffix += ' = ' + self.default
        return self._StringHelper(self.__class__.__name__, suffix)


def _DeclarationToParts(parts):
    name = parts.pop()
    modifiers = []
    type_name = []
    for p in parts:
        if keywords.IsKeyword(p.name):
            modifiers.append(p.name)
        elif p.name == '<':
            # Ignore the template portion, we know that must be used.
            # TODO(nnorwitz): we really need to keep the templated name
            # separately so we know to keep the header that included it.
            type_name.pop()
        elif p.name not in ('*', '&', '>'):
            # Ensure that names have a space between them.
            if (type_name and type_name[-1].token_type == tokenize.NAME and
                p.token_type == tokenize.NAME):
                type_name.append(tokenize.Token(tokenize.SYNTAX, ' ', 0, 0))
            type_name.append(p)
    type_name = ''.join([t.name for t in type_name])
    return name.name, type_name, modifiers


def _SequenceToParameters(seq):
    if not seq:
        return []

    result = []
    name = type_name = ''
    type_modifiers = []
    pointer = reference = False
    first_token = default = None
    for s in seq:
        if not first_token:
            first_token = s
        if s.name == ',':
            # TODO(nnorwitz): handle default values.
            name, type_name, modifiers = _DeclarationToParts(type_modifiers)
            p = Parameter(first_token.start, first_token.end, name, type_name,
                          modifiers, reference, pointer, None, default)
            result.append(p)
            name = type_name = ''
            type_modifiers = []
            pointer = reference = False
            first_token = default = None
        elif s.name == '*':
            pointer = True
        elif s.name == '&':
            reference = True
        else:
            type_modifiers.append(s)
    name, type_name, modifiers = _DeclarationToParts(type_modifiers)
    p = Parameter(first_token.start, first_token.end, name, type_name,
                  modifiers, reference, pointer, None, default)
    result.append(p)
    return result


def CreateReturnType(return_type_seq):
    start = return_type_seq[0].start
    end = return_type_seq[-1].end
    bogus_name = tokenize.Token(tokenize.NAME, '<return value>', 0, 0)
    return_type_seq.append(bogus_name)
    name, type_name, modifiers = _DeclarationToParts(return_type_seq)
    names = [n.name for n in return_type_seq]
    reference = '&' in names
    pointer = '*' in names
    return VariableDeclaration(start, end, name, type_name, modifiers,
                               reference, pointer, None, None)


class _GenericDeclaration(Node):
    def __init__(self, start, end, name, namespace):
        Node.__init__(self, start, end)
        self.name = name
        self.namespace = namespace[:]

    def FullName(self):
        prefix = ''
        if self.namespace and self.namespace[-1]:
            prefix = '::'.join(self.namespace) + '::'
        return prefix + self.name

    def _TypeStringHelper(self, suffix):
        if self.namespace:
            names = [n or '<anonymous>' for n in self.namespace]
            suffix += ' in ' + '::'.join(names)
        return self._StringHelper(self.__class__.__name__, suffix)


# TODO(nnorwitz): merge with Parameter in some way?
class VariableDeclaration(_GenericDeclaration):
    def __init__(self, start, end, name, type_name, type_modifiers,
                 reference, pointer, templated_types, initial_value):
        _GenericDeclaration.__init__(self, start, end, name, [])
        self.type_name = type_name
        self.type_modifiers = type_modifiers
        self.reference = reference
        self.pointer = pointer
        self.initial_value = initial_value
        self.templated_types = templated_types

    def Requires(self, node):
        # TODO(nnorwitz): handle namespaces, etc.
        return self.type_name == node.name

    def ToString(self):
        """Return a string that tries to reconstitute the variable decl."""
        modifiers = ' '.join(self.type_modifiers)
        syntax = ''
        if self.reference:
            syntax += '&'
        if self.pointer:
            syntax += '*'
        # TODO(nnorwitz): add templated_types.
        suffix = '%s %s%s %s' % (modifiers, self.type_name, syntax, self.name)
        if self.initial_value:
            suffix += ' = ' + self.initial_value
        return suffix

    def __str__(self):
        return self._StringHelper(self.__class__.__name__, self.ToString())


class Typedef(_GenericDeclaration):
    def __init__(self, start, end, name, alias, namespace):
        _GenericDeclaration.__init__(self, start, end, name, namespace)
        self.alias = alias

    def IsDefinition(self):
        return True

    def IsExportable(self):
        return True

    def Requires(self, node):
        # TODO(nnorwitz): handle namespaces, etc.
        name = node.name
        for token in self.alias:
            if token is not None and name == token.name:
                return True
        return False

    def __str__(self):
        suffix = '%s, %s' % (self.name, self.alias)
        return self._TypeStringHelper(suffix)


class _NestedType(_GenericDeclaration):
    def __init__(self, start, end, name, fields, namespace):
        _GenericDeclaration.__init__(self, start, end, name, namespace)
        self.fields = fields

    def IsDefinition(self):
        return True

    def IsExportable(self):
        return True

    def __str__(self):
        suffix = '%s, {%s}' % (self.name, self.fields)
        return self._TypeStringHelper(suffix)


class Union(_NestedType):
    pass


class Enum(_NestedType):
    pass


class Class(_GenericDeclaration):
    def __init__(self, start, end, name, bases, templated_types, body, namespace):
        _GenericDeclaration.__init__(self, start, end, name, namespace)
